const { email, firstName, lastName, phone, fieldValues } = $.input;
if (!email) throw new Error('email is required');
const contact = { email };
if (firstName) contact.firstName = firstName;
if (lastName) contact.lastName = lastName;
if (phone) contact.phone = phone;
if (fieldValues && fieldValues.length > 0) contact.fieldValues = fieldValues;
return { contact };

const tagId = $.input.tagId;
const contactId = $.steps.createContact.response?.contact?.id;
return { shouldTag: !!(tagId && contactId), contactId: contactId || '', tagId: tagId || '' };

const resp = $.steps.createContact.response || {};
const contact = resp.contact || {};
const tagged = $.steps.addTag?.response?.contactTag ? true : false;
return {
  contactId: contact.id || '',
  email: contact.email || $.input.email,
  firstName: contact.firstName || '',
  lastName: contact.lastName || '',
  created: !!contact.id,
  tagged,
  summary: contact.id
    ? `Created contact ${contact.email || $.input.email}${tagged ? ' (tagged)' : ''}`
    : 'Failed to create contact'
};
